function doble(x) {
  if (Array.isArray(x)) {
    const resultado = [];
    for (let fila = 0; fila < x.length; fila++) {
      resultado[fila] = new Array(x[fila].length);
      for (let columna = 0; columna < x[fila].length; columna++) {
        resultado[fila][columna] = Number(x[fila][columna]) * 2;
      }
    }
    return resultado;
  }
  return x * 2;
}
